# %% ../nbs/00_load_sps_library.ipynb 3
import numpy as np
import os
import matplotlib.pylab as plt
from .load_sim_stellar_catalog import Z_SOLAR_PADOVA, H0
from importlib.resources import files as _pkg_files

# %% ../nbs/00_load_sps_library.ipynb 5
STELLAR_LIBRARY_DIR = "data/sps_library_data/"
LIBRARY_FLUX_FILE = str(_pkg_files("watercolor").joinpath(STELLAR_LIBRARY_DIR, "ssp_spec_flux_lines.npy"))
LIBRARY_WAVE_FILE = str(_pkg_files("watercolor").joinpath(STELLAR_LIBRARY_DIR, "ssp_spec_wave.npy"))
LIBRARY_AGE_FILE = str(_pkg_files("watercolor").joinpath(STELLAR_LIBRARY_DIR, "log_age.npy"))
LIBRARY_METAL_FILE = str(_pkg_files("watercolor").joinpath(STELLAR_LIBRARY_DIR, "zlegend.npy"))

# %% ../nbs/00_load_sps_library.ipynb 6
C_ANGSTROM_PER_S = 2.99792458e18 # Speed of light in Angstrom/s

def load_fsps_spectral_library(flux_fileIn:str=LIBRARY_FLUX_FILE, # Input flux file of the stellar spectra library
                               wave_fileIn:str=LIBRARY_WAVE_FILE, # Input wavelength file of the stellar spectra library
                               per_angstrom:bool=True, # Convert the stored L_nu [Lsun/Hz] to L_lambda [Lsun/A]
                              ) -> tuple: #Fluxes (Lsun/A per Msun formed), wavelengths (A)
    '''
    Load the SSP spectral library.

    The bundled `ssp_spec_flux_lines.npy` is the native FSPS output
    (Padova isochrones + BaSeL, Kroupa IMF, nebular emission on): **L_nu in
    Lsun/Hz per 1 Msun of stars formed** -- checked against python-fsps
    (`StellarPopulation.get_spectrum(peraa=False)`), ratio 1.000 over the
    whole grid. Everything downstream (CSP sums, bolometric integrals over
    wavelength, the redshift/dimming step, dust) works in L_lambda, so convert
    here, once: L_lambda = L_nu * c / lambda^2. Reading the stored numbers as
    Lsun/A instead tilts every SED by lambda^2 (far too red: +0.6 in u-g,
    +1.0 in g-i) and leaves it ~1e10x too faint.
    '''
    spec_flux = np.load(flux_fileIn)
    spec_wave = np.load(wave_fileIn)
    if per_angstrom:
        spec_flux = spec_flux * C_ANGSTROM_PER_S / spec_wave**2
    return spec_flux, spec_wave

# %% ../nbs/00_load_sps_library.ipynb 7
def _load_fsps_age(age_fileIn:str=LIBRARY_AGE_FILE # Input age file of the stellar spectra library 
                  )-> np.array: # Age in Gyr
    
    # log_age.npy stores log10(age) in years; subtracting 9 converts to log10(age/Gyr)
    log_age_gyr = np.load( age_fileIn ) - 9
    age_fsps_gyr = 10**log_age_gyr  # Gyr
    return age_fsps_gyr

# %% ../nbs/00_load_sps_library.ipynb 8
def _load_fsps_metallicity(metal_fileIn:str=LIBRARY_METAL_FILE, # Input metallicity file of the stellar spectra library
                           Z_solar:np.float32=Z_SOLAR_PADOVA # Solar metallicity in Padova
                          ) -> np.array: #Metallicity values in Z/Z_solar units
    Z_legend = np.load( metal_fileIn )
    Z_padova_fsps = Z_legend/Z_solar
    return Z_padova_fsps

# %% ../nbs/00_load_sps_library.ipynb 9
def load_fsps_age_metallicity(age_fileIn:str=LIBRARY_AGE_FILE, # Input metallicity file of the stellar spectra library
                              metal_fileIn:str=LIBRARY_METAL_FILE, # Input age file of the stellar spectra library 
                              Z_solar:np.float32=Z_SOLAR_PADOVA # Solar metallicity in Padova
                             )-> tuple: # Age in Gyr, Metallicity in Z/Z_sun
    
    age_fsps_gyr = _load_fsps_age(age_fileIn)
    
    Z_padova = _load_fsps_metallicity(metal_fileIn, Z_solar)
    
    return age_fsps_gyr, Z_padova
